-- Official OBEC 2021 must-know/should-know indicators for Arts P4.
with seed(standard_code,code,name,seq,classification) as (values
('ศ 1.1','ARTS-P4-01','เปรียบเทียบรูปลักษณะของรูปร่าง รูปทรง ในธรรมชาติ สิ่งแวดล้อม และงานทัศนศิลป์',1,'should_know'),
('ศ 1.1','ARTS-P4-02','จำแนกทัศนธาตุของสิ่งต่าง ๆ ในธรรมชาติ สิ่งแวดล้อม และงานทัศนศิลป์ โดยเน้นเรื่องเส้น สี รูปร่าง รูปทรงพื้นผิวและพื้นที่ว่าง',2,'must_know'),
('ศ 1.1','ARTS-P4-03','อภิปรายเกี่ยวกับอิทธิพลของสีธรรมชาติและสีธรรมะเย็น ที่มีต่ออารมณ์ของมนุษย์',3,'should_know'),
('ศ 1.1','ARTS-P4-04','วาดภาพระบายสี โดยใช้สีวรรณะอุ่น และสีวรรณะเย็น ถ่ายทอดความรู้สึกและจินตนาการ',4,'should_know'),
('ศ 1.1','ARTS-P4-05','เลือกใช้วรรณะสีเพื่อถ่ายทอดอารมณ์ ความรู้สึก ในการสร้างงานทัศนศิลป์',5,'should_know'),
('ศ 1.1','ARTS-P4-06','มีทักษะพื้นฐานในการใช้วัสดุ อุปกรณ์ สร้างสรรค์งานพิมพ์ภาพ',6,'must_know'),
('ศ 1.1','ARTS-P4-07','มีทักษะพื้นฐานในการใช้วัสดุ อุปกรณ์ สร้างสรรค์งานวาดภาพระบายสี',7,'should_know'),
('ศ 1.1','ARTS-P4-08','บรรยายลักษณะของภาพโดยเน้นเรื่องการจัดระยะ ความลึก น้ำหนัก และแสงเงาในภาพ',8,'must_know'),
('ศ 1.1','ARTS-P4-09','เปรียบเทียบความคิดความรู้สึกที่ถ่ายทอดผ่านงานทัศนศิลป์ของตนเองและบุคคลอื่น',9,'should_know'),
('ศ 1.2','ARTS-P4-10','ระบุ และอภิปรายเกี่ยวกับงานทัศนศิลป์ ในเหตุการณ์และงานเฉลิมฉลองของวัฒนธรรม ในท้องถิ่น',10,'should_know'),
('ศ 1.2','ARTS-P4-11','บรรยายเกี่ยวกับงานทัศนศิลป์ที่มาจากวัฒนธรรมต่าง ๆ',11,'must_know'),
('ศ 2.1','ARTS-P4-12','บอกประโยคเพลงอย่างง่าย',12,'must_know'),
('ศ 2.1','ARTS-P4-13','จำแนกประเภทของเครื่องดนตรีที่ใช้ในเพลงที่ฟัง',13,'must_know'),
('ศ 2.1','ARTS-P4-14','ระบุทิศทางการเคลื่อนที่ขึ้น - ลงง่าย ๆ ของทำนอง รูปแบบจังหวะ และความเร็วของจังหวะในเพลงที่ฟัง',14,'must_know'),
('ศ 2.1','ARTS-P4-15','อ่าน เขียนโน้ตดนตรีไทยและสากล',15,'must_know'),
('ศ 2.1','ARTS-P4-16','ร้องเพลงโดยใช้ช่วงเสียงที่เหมาะสมกับตนเอง',16,'must_know'),
('ศ 2.1','ARTS-P4-17','ใช้และเก็บเครื่องดนตรีอย่างถูกต้องและปลอดภัย',17,'should_know'),
('ศ 2.1','ARTS-P4-18','ระบุว่าดนตรีสามารถใช้ในการสื่อเรื่องราว',18,'should_know'),
('ศ 2.2','ARTS-P4-19','บอกแหล่งที่มาและความสัมพันธ์ของวิถีชีวิตไทย ที่สะท้อนในดนตรีและเพลงท้องถิ่น',19,'should_know'),
('ศ 2.2','ARTS-P4-20','ระบุความสำคัญในการอนุรักษ์ส่งเสริมวัฒนธรรมทางดนตรี',20,'must_know'),
('ศ 3.1','ARTS-P4-21','ระบุทักษะพื้นฐานทางนาฏศิลป์และการละครที่ใช้สื่อความหมายและอารมณ์',21,'must_know'),
('ศ 3.1','ARTS-P4-22','ใช้ภาษาท่าและนาฏยศัพท์ หรือศัพท์ทางการละครง่าย ๆ ในการถ่ายทอดเรื่องราว',22,'must_know'),
('ศ 3.1','ARTS-P4-23','แสดงการเคลื่อนไหวในจังหวะต่าง ๆ ตามความคิดของตน',23,'should_know'),
('ศ 3.1','ARTS-P4-24','แสดงนาฏศิลป์เป็นคู่และหมู่',24,'must_know'),
('ศ 3.1','ARTS-P4-25','เล่าสิ่งที่ชื่นชอบในการแสดง โดยเน้นจุดสำคัญของเรื่อง และลักษณะเด่นของตัวละคร',25,'should_know'),
('ศ 3.2','ARTS-P4-26','อธิบายประวัติความเป็นมาของนาฏศิลป์ หรือชุดการแสดงอย่างง่าย ๆ',26,'must_know'),
('ศ 3.2','ARTS-P4-27','ระบุเหตุผลที่ควรรักษาและสืบทอดการแสดงนาฏศิลป์',27,'must_know'),
('ศ 3.2','ARTS-P4-28','เปรียบเทียบการแสดงนาฏศิลป์กับการแสดงที่มาจากวัฒนธรรมอื่น',28,'should_know'),
('ศ 3.2','ARTS-P4-29','อธิบายความสำคัญของการแสดงความเคารพในการเรียนและการแสดงนาฏศิลป์',29,'should_know')
), subject as (select s.id subject_id,sk.id skill_id,t.id topic_id,t.code standard_code from learning_subjects s join learning_skills sk on sk.subject_id=s.id join learning_topics t on t.skill_id=sk.id where s.code='ARTS' and sk.code='ARTS'), inserted as (insert into learning_objectives(topic_id,code,name,sequence_no) select subject.topic_id,seed.code,seed.name,seed.seq from seed join subject using(standard_code) on conflict(topic_id,code) do update set name=excluded.name,sequence_no=excluded.sequence_no returning id,code) insert into learning_objective_alignments(objective_id,curriculum_id,grade_level_id,required,indicator_classification) select o.id,c.id,g.id,(seed.classification='must_know'),seed.classification from seed join inserted o on o.code=seed.code join learning_curricula c on c.code='TH-BASIC-CORE-2008-2017' join learning_grade_levels g on g.curriculum_id=c.id and g.code='P4' on conflict(objective_id,curriculum_id,grade_level_id) do update set required=excluded.required,indicator_classification=excluded.indicator_classification;